  "insights.principles.disclaimer": { en: "Unleash Your Power is independent study and coaching inspired by the Master Key System. It is not affiliated with or endorsed by the historical authors discussed here. Individual outcomes depend on circumstances, participation and consistent practice.", es: "Unleash Your Power es un servicio independiente de estudio y coaching inspirado en el Master Key System. No está afiliado ni respaldado por los autores históricos mencionados aquí. Los resultados individuales dependen de las circunstancias, la participación y la práctica constante." },
  "resources.audio.eyebrow": { en: "LISTEN AND STUDY", es: "ESCUCHA Y ESTUDIA" },
