  "route.masterKeySystemOnlineCourse.heading": { en: "Master Key System Online Course", es: "Curso online del Master Key System" },
  "route.masterKeySystemOnlineCourse.purpose": { en: "A practical online 24-week study journey through the Master Key System, with weekly exercises, reflection and optional coaching support.", es: "Un recorrido práctico online de estudio de 24 semanas por el Master Key System, con ejercicios semanales, reflexión y apoyo opcional de coaching." },
  "route.masterKeySystemOnlineCourse.journeyHeading": { en: "A structured 24-week study journey", es: "Un recorrido de estudio estructurado de 24 semanas" },
  "route.masterKeySystemOnlineCourse.journeyBody": { en: "Move through four progressive stages at a steady pace, using each lesson to build understanding before applying the next principle.", es: "Avanza por cuatro etapas progresivas a un ritmo constante, usando cada lección para comprender antes de aplicar el siguiente principio." },
  "route.masterKeySystemOnlineCourse.practiceHeading": { en: "Practical Master Key exercises", es: "Ejercicios prácticos del Master Key" },
  "route.masterKeySystemOnlineCourse.practiceBody": { en: "Each week pairs the reading with a clear exercise and a question to help you observe, practise and bring the ideas into everyday decisions.", es: "Cada semana combina la lectura con un ejercicio claro y una pregunta para observar, practicar y llevar las ideas a las decisiones diarias." },
  "route.masterKeySystemOnlineCourse.supportHeading": { en: "Study with guidance when you need it", es: "Estudia con orientación cuando la necesites" },
  "route.masterKeySystemOnlineCourse.supportBody": { en: "The free resources and AI study tools are available as you learn, while personal coaching with Tariq offers additional structure, accountability and reflection.", es: "Los recursos gratuitos y las herramientas de estudio con IA están disponibles durante el aprendizaje, mientras que el coaching personal con Tariq ofrece estructura, responsabilidad y reflexión adicionales." },
  "route.masterKeySystemOnlineCourse.fitHeading": { en: "Who this online course is for", es: "Para quién es este curso online" },
  "route.masterKeySystemOnlineCourse.fitBody": { en: "It is for people who want a calm, consistent way to study the Master Key System and test its practical exercises for themselves. Begin with the free 7-day experience before deciding whether the full journey fits you.", es: "Es para personas que desean estudiar el Master Key System de forma tranquila y constante y probar sus ejercicios prácticos. Empieza con la experiencia gratuita de 7 días antes de decidir si el recorrido completo es para ti." },
