  "phase2.contact.questionBody": { en: "If you are not ready to discuss coaching, ask what you need to know about the Master Key System, the free experience or how the journey works.", es: "Si aún no estás listo para hablar de coaching, pregunta lo que necesites saber sobre el Master Key System, la experiencia gratuita o cómo funciona el recorrido." },
  "phase2.contact.questionAction": { en: "ASK A QUESTION", es: "HACER UNA PREGUNTA" },
